/* Chinese Econ JMC — placement statistics page. Data comes from data.js (generated by scripts/build.py). */
(function () {
  "use strict";

  const D = window.JMC_DATA;
  const $ = (id) => document.getElementById(id);
  if (!D) { $("mix").textContent = "data.js 未找到，请先运行 python scripts/build.py"; return; }
  $("generated").textContent = D.generated;

  const esc = (s) => String(s ?? "").replace(/[&<>"']/g, (c) => ({ "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;", "'": "&#39;" }[c]));
  const pct = (k, n) => (n ? Math.round(100 * k / n) : 0);

  // placement categories, in stacking order; colors live in stats.css (.k-<key>)
  const TYPES = [
    { key: "fac", label: "教职", test: (c) => c.placement_type === "Faculty" },
    { key: "pd", label: "博后", test: (c) => c.placement_type === "Postdoc" },
    { key: "ind", label: "业界及其他", test: (c) => c.placement_type === "Industry & Other" },
    { key: "def", label: "延期", test: (c) => c.placement_type === "Deferred" },
    { key: "unk", label: "未知", test: (c) => !c.placement },
  ];
  const typeOf = (c) => TYPES.find((t) => t.test(c)).key;

  const REGIONS = D.placement_regions || [];
  const regionOf = (c) => c.placement_region || "未归类";

  // cycles that already have placement information, newest first
  const cycles = D.cycles.filter((cy) => D.candidates.some((c) => c.cycle === cy && c.placement));
  const inCycle = (cy) => D.candidates.filter((c) => c.cycle === cy);

  // ------------------------------------------------------------ tooltip ----
  const tip = $("tip");
  document.addEventListener("mouseover", (e) => {
    const t = e.target.closest("[data-tip]");
    if (!t) { tip.hidden = true; return; }
    tip.innerHTML = t.dataset.tip;
    tip.hidden = false;
  });
  document.addEventListener("mousemove", (e) => {
    if (tip.hidden) return;
    const pad = 14, w = tip.offsetWidth, h = tip.offsetHeight;
    let x = e.clientX + pad, y = e.clientY + pad;
    if (x + w > window.innerWidth - 8) x = e.clientX - w - pad;
    if (y + h > window.innerHeight - 8) y = e.clientY - h - pad;
    tip.style.transform = `translate(${x}px, ${y}px)`;
  });
  document.addEventListener("mouseleave", () => { tip.hidden = true; });

  const legend = (keys) => `<div class="legend">${TYPES.filter((t) => keys.includes(t.key))
    .map((t) => `<span><i class="sw k-${t.key}"></i>${t.label}</span>`).join("")}</div>`;

  // stacked 100% bar; `parts` = [{key, label, k}], total n
  function stack(parts, n, title) {
    return `<div class="stack">${parts.filter((p) => p.k).map((p) =>
      `<span class="seg-${p.key} k-${p.key}" style="flex-grow:${p.k}"
        data-tip="<b>${esc(title)}</b><br>${p.label}：${p.k} 人（${pct(p.k, n)}%）"></span>`).join("")}</div>`;
  }

  // ------------------------------------------- 1. placement mix by cycle ----
  function renderMix() {
    const rows = cycles.map((cy) => {
      const list = inCycle(cy);
      const parts = TYPES.map((t) => ({ key: t.key, label: t.label, k: list.filter(t.test).length }));
      return { cy, n: list.length, parts };
    });
    const bars = rows.map((r) => `
      <div class="mix-row">
        <div class="mix-label"><b>${r.cy}</b><span>${r.n} 人</span></div>
        ${stack(r.parts, r.n, r.cy)}
      </div>`).join("");
    const table = `<table class="data">
      <thead><tr><th>年度</th>${TYPES.map((t) => `<th><i class="sw k-${t.key}"></i>${t.label}</th>`).join("")}<th>已知去向中教职</th></tr></thead>
      <tbody>${rows.map((r) => {
        const known = r.parts.filter((p) => p.key !== "unk").reduce((s, p) => s + p.k, 0);
        return `<tr><td>${r.cy}</td>${r.parts.map((p) => `<td>${p.k}<span class="pc">${pct(p.k, r.n)}%</span></td>`).join("")}
          <td>${pct(r.parts[0].k, known)}%</td></tr>`;
      }).join("")}</tbody></table>`;
    $("mix").innerHTML = legend(TYPES.map((t) => t.key)) + bars + `<div class="scroll-x">${table}</div>`;
  }

  // ----------------------------------- 2. faculty region x cycle (matrix) ----
  function renderRegions() {
    const cols = [...cycles].reverse().map((cy) => ({ label: cy, list: inCycle(cy).filter((c) => c.placement_type === "Faculty") }));
    cols.push({ label: "合计", list: cols.flatMap((c) => c.list), total: true });
    const count = (list, r) => list.filter((c) => regionOf(c) === r).length;
    const total = cols[cols.length - 1];
    const regions = [...new Set(total.list.map(regionOf))]
      .sort((a, b) => count(total.list, b) - count(total.list, a) || REGIONS.indexOf(a) - REGIONS.indexOf(b));
    const maxShare = Math.max(...cols.flatMap((col) => regions.map((r) => count(col.list, r) / (col.list.length || 1))));
    const head = `<div class="rm-row rm-head" style="--cols:${cols.length}"><span></span>${cols.map((col) =>
      `<span class="${col.total ? "tot" : ""}">${col.label}<em>${col.list.length} 人</em></span>`).join("")}</div>`;
    const body = regions.map((r) => `<div class="rm-row" style="--cols:${cols.length}"><span class="rl">${esc(r)}</span>${cols.map((col) => {
      const k = count(col.list, r), p = pct(k, col.list.length);
      const w = col.list.length ? (100 * (k / col.list.length) / maxShare).toFixed(1) : 0;
      return `<span class="cell ${col.total ? "tot" : ""}" data-tip="<b>${esc(r)} · ${col.label}</b><br>${k} 人，占当年教职 ${p}%">
        <span class="bar"><span class="fill k-fac" style="width:${k ? w : 0}%"></span></span><span class="v">${k ? `${k} · ${p}%` : "–"}</span></span>`;
    }).join("")}</div>`).join("");
    $("regions").innerHTML = `<div class="scroll-x"><div class="rmatrix">${head}${body}</div></div>`;
  }

  // ---------------------------------------------------- cycle selection ----
  const SEG = [{ v: "all", label: "全部年度" }, ...cycles.map((cy) => ({ v: cy, label: cy }))];
  let sel = "all";
  try { const s = localStorage.getItem("jmc-stats-cycle"); if (SEG.some((o) => o.v === s)) sel = s; } catch (e) { /* storage unavailable */ }
  const selected = () => D.candidates.filter((c) => (sel === "all" ? cycles.includes(c.cycle) : c.cycle === sel));

  function renderSeg() {
    $("cycle-seg").innerHTML = SEG.map((o) =>
      `<button type="button" role="tab" aria-selected="${o.v === sel}" data-v="${o.v}" class="${o.v === sel ? "active" : ""}">${o.label}</button>`).join("");
  }
  $("cycle-seg").addEventListener("click", (e) => {
    const b = e.target.closest("button[data-v]");
    if (!b) return;
    sel = b.dataset.v;
    try { localStorage.setItem("jmc-stats-cycle", sel); } catch (err) { /* ignore */ }
    renderDetail();
  });

  // ------------------------------------------------------------- KPIs ----
  function renderKpis(list) {
    const known = list.filter((c) => c.placement && c.placement_type !== "Deferred");
    const fac = list.filter((c) => c.placement_type === "Faculty");
    const home = fac.filter((c) => ["中国大陆", "港澳"].includes(c.placement_region)).length;
    const us = fac.filter((c) => c.placement_region === "美国").length;
    $("kpis").innerHTML = `
      <div class="stat"><div class="n">${list.length}</div><div class="l">候选人</div></div>
      <div class="stat"><div class="n">${known.length}</div><div class="l">已有最终去向</div><div class="sub">占 ${pct(known.length, list.length)}%（不含延期）</div></div>
      <div class="stat"><div class="n">${fac.length}</div><div class="l">教职</div><div class="sub">占已有最终去向 ${pct(fac.length, known.length)}%</div></div>
      <div class="stat"><div class="n">${pct(home, fac.length)}%</div><div class="l">教职在中国大陆及港澳</div><div class="sub">${home} 人 · 美国 ${us} 人（${pct(us, fac.length)}%）</div></div>`;
  }

  // -------------------------------------- 3. PhD school tier x outcome ----
  const TIERS = [
    { label: "美国 #1–10", test: (c) => c.region === "美国区域" && c.rank && c.rank <= 10 },
    { label: "美国 #11–20", test: (c) => c.region === "美国区域" && c.rank > 10 && c.rank <= 20 },
    { label: "美国 #21–40", test: (c) => c.region === "美国区域" && c.rank > 20 && c.rank <= 40 },
    { label: "美国 #41+", test: (c) => c.region === "美国区域" && (c.rank > 40 || !c.rank) },
    { label: "非美国院校", test: (c) => c.region !== "美国区域" },
  ];
  const OUTCOMES = [
    { label: "中国大陆", group: "教职", test: (c) => c.placement_type === "Faculty" && c.placement_region === "中国大陆" },
    { label: "港澳", group: "教职", test: (c) => c.placement_type === "Faculty" && c.placement_region === "港澳" },
    { label: "美国", group: "教职", test: (c) => c.placement_type === "Faculty" && c.placement_region === "美国" },
    { label: "其他海外", group: "教职", test: (c) => c.placement_type === "Faculty" && !["中国大陆", "港澳", "美国"].includes(c.placement_region) },
    { label: "博后", test: (c) => c.placement_type === "Postdoc" },
    { label: "业界及其他", test: (c) => c.placement_type === "Industry & Other" },
    { label: "延期", test: (c) => c.placement_type === "Deferred" },
    { label: "未知", test: (c) => !c.placement },
  ];

  function renderTiers(list) {
    const rows = TIERS.map((t) => ({ label: t.label, list: list.filter(t.test) })).filter((r) => r.list.length);
    const cells = rows.map((r) => OUTCOMES.map((o) => r.list.filter(o.test).length));
    const maxShare = Math.max(...rows.flatMap((r, i) => cells[i].map((k) => k / r.list.length)));
    const head = `<thead>
      <tr><th rowspan="2">博士院校</th><th rowspan="2" class="num">人数</th><th colspan="4" class="grp">教职</th><th colspan="4"></th></tr>
      <tr>${OUTCOMES.map((o) => `<th>${o.label}</th>`).join("")}</tr></thead>`;
    const body = rows.map((r, i) => `<tr><th>${r.label}</th><td class="num">${r.list.length}</td>${cells[i].map((k, j) => {
      const share = k / r.list.length, a = maxShare ? share / maxShare : 0;
      const o = OUTCOMES[j], name = o.group ? `${o.group} · ${o.label}` : o.label;
      return `<td class="hm ${a > 0.55 ? "hot" : ""}" style="--a:${(a * 100).toFixed(0)}%"
        data-tip="<b>${r.label} → ${name}</b><br>${k} / ${r.list.length} 人（${pct(k, r.list.length)}%）">${k ? `${k}<span class="pc">${pct(k, r.list.length)}%</span>` : "<span class='z'>·</span>"}</td>`;
    }).join("")}</tr>`).join("");
    $("tiers").innerHTML = `<table class="heat">${head}<tbody>${body}</tbody></table>`;
  }

  // ------------------------------------------- 4. research field x outcome ----
  function renderFields(list) {
    const known = list.filter((c) => ["Faculty", "Postdoc", "Industry & Other"].includes(c.placement_type));
    const keys = ["fac", "pd", "ind"];
    const rows = (D.field_categories || []).filter((f) => f !== "Other").map((f) => {
      const g = known.filter((c) => (c.fields || []).includes(f));
      return { f, n: g.length, parts: keys.map((key) => {
        const t = TYPES.find((x) => x.key === key);
        return { key, label: t.label, k: g.filter(t.test).length };
      }) };
    }).filter((r) => r.n >= 10).sort((a, b) => b.parts[0].k / b.n - a.parts[0].k / a.n || b.n - a.n);
    if (!rows.length) { $("fields").innerHTML = `<p class="note">该年度暂无足够数据。</p>`; return; }
    $("fields").innerHTML = legend(keys) + rows.map((r) => `
      <div class="f-row">
        <span class="f-label">${esc(r.f)}</span>
        ${stack(r.parts, r.n, `${r.f}（n=${r.n}）`)}
        <span class="f-val">${pct(r.parts[0].k, r.n)}%<em>n=${r.n}</em></span>
      </div>`).join("") + `<p class="note small">右侧为教职比例；少于 10 人的领域和"Other"不列出。</p>`;
  }

  // -------------------------------------- 5. top faculty institutions ----
  function renderInsts(list) {
    const fac = list.filter((c) => c.placement_type === "Faculty");
    const m = new Map();
    for (const c of fac) {
      const k = c.placement_inst || "其他（未归类）";
      if (!m.has(k)) m.set(k, { n: 0, region: c.placement_region });
      m.get(k).n += 1;
    }
    const all = [...m].sort((a, b) => b[1].n - a[1].n || a[0].localeCompare(b[0], "zh"));
    const top = all.filter(([, v]) => v.n >= 2).slice(0, 15);
    const rest = all.length - top.length, restN = fac.length - top.reduce((s, [, v]) => s + v.n, 0);
    if (!top.length) { $("insts").innerHTML = `<p class="note">该年度没有机构录用 2 人及以上。</p>`; return; }
    const max = top[0][1].n;
    $("insts").innerHTML = top.map(([name, v]) => `
      <div class="i-row" data-tip="<b>${esc(name)}</b>（${esc(v.region || "")}）<br>${v.n} 人，占教职 ${pct(v.n, fac.length)}%">
        <span class="i-label">${esc(name)}<em>${esc(v.region || "")}</em></span>
        <span class="bar"><span class="fill k-fac" style="width:${(100 * v.n / max).toFixed(1)}%"></span></span>
        <span class="v">${v.n}</span>
      </div>`).join("") +
      (rest ? `<p class="note small">另有 ${rest} 家机构共 ${restN} 人。</p>` : "");
  }

  function renderDetail() {
    renderSeg();
    const list = selected();
    renderKpis(list);
    renderTiers(list);
    renderFields(list);
    renderInsts(list);
  }

  renderMix();
  renderRegions();
  renderDetail();
})();
